import styled from '@emotion/styled';
import { theme } from 'theme';

export const StyledBreadcrumbContainer = styled.div({
  display: 'flex',
  alignItems: 'center',
  flexWrap: 'wrap',
  gap: '4px',
  paddingLeft: '24px',
  paddingRight: '24px',
  marginLeft: '-24px',
  marginRight: '-24px',
});

interface StyledChipProps {
  $isHighlighted?: boolean;
  $isInteractive?: boolean;
}

export const StyledChip = styled('div', {
  shouldForwardProp: (propName) =>
    !['$isHighlighted', '$isInteractive'].includes(propName),
})<StyledChipProps>(({ $isHighlighted, $isInteractive }) => ({
  display: 'inline-flex',
  alignItems: 'center',
  gap: '4px',
  padding: '4px 10px',
  border: '1px solid #D9D9D9',
  borderRadius: '1rem',
  backgroundColor: '#FFFFFF',
  fontSize: theme.fonts.fontSizes['2'],
  fontWeight: theme.fonts.fontWeights.medium,
  fontFamily: theme.fonts.paragraph,
  color: '#141414',
  lineHeight: '20px',
  whiteSpace: 'nowrap',
  cursor: 'default',
  ...($isHighlighted && {
    backgroundColor: '#FFF1C2',
    borderColor: '#FFF1C2',
  }),
  ...($isInteractive && {
    cursor: 'pointer',
    '&:hover': { opacity: 0.8 },
  }),
}));

export const StyledChipLabel = styled.span({
  overflow: 'hidden',
  textOverflow: 'ellipsis',
  whiteSpace: 'nowrap',
  maxWidth: '200px',
});

export const StyledCloseButton = styled.button({
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
  padding: '0',
  background: 'white',
  border: 'none',
  cursor: 'pointer',
  color: '#141414',
  borderRadius: '50%',
  width: '16px',
  height: '16px',

  svg: {
    width: '10px',
    height: '10px',
  },

  '&:hover': {
    backgroundColor: 'rgba(20, 20, 20, 0.08)',
  },

  '&:focus-visible': {
    outline: '2px solid #141414',
    outlineOffset: '2px',
  },
});

export const StyledSeparator = styled.span({
  display: 'inline-flex',
  alignItems: 'center',
  padding: '0 4px',
  userSelect: 'none',
});
